static int 
dtb_ttsnoop_ttsnoop_win_create(
    DtbTtsnoopTtsnoopWinInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Display	*display= (parent == NULL? NULL:XtDisplay(parent));
    Pixmap	icon_pixmap = 0;
    Pixmap	icon_mask_pixmap = 0;
    
    if (instance->ttsnoopWin == NULL) {
        dtb_cvt_image_file_to_pixmap(parent,
            "DtTtsnp.l", &icon_pixmap);
        dtb_cvt_image_file_to_pixmap(parent,
            "DtTtsnp.l_m", &icon_mask_pixmap);
        instance->ttsnoopWin =
            XtVaCreatePopupShell("ttsnoopWin",
                topLevelShellWidgetClass,
                parent,
                XmNallowShellResize, True,
                XmNtitle, "ttsnoop",
                XmNiconMask, icon_mask_pixmap,
                XmNiconPixmap, icon_pixmap,
                XmNinitialState, NormalState,
                XmNbackground, dtb_cvt_string_to_pixel(parent, "white"),
                NULL);
    }
    if (instance->ttsnoopWin == NULL)
        return -1;

    if (instance->ttsnoopWin_mainwin == NULL) {
        instance->ttsnoopWin_mainwin =
            XtVaCreateWidget("dtb_ttsnoop_ttsnoopWin_mainwin",
                xmMainWindowWidgetClass,
                instance->ttsnoopWin,
                XmNbackground, dtb_cvt_string_to_pixel(instance->ttsnoopWin, "white"),
                NULL);
    }
    if (instance->ttsnoopWin_mainwin == NULL)
        return -1;

    if (instance->ttsnoopWin_form == NULL) {
        instance->ttsnoopWin_form =
            XtVaCreateWidget("ttsnoopWin_form",
                xmFormWidgetClass,
                instance->ttsnoopWin_mainwin,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNresizePolicy, XmRESIZE_GROW,
                XmNheight, 257,
                XmNwidth, 580,
                XmNbackground, dtb_cvt_string_to_pixel(instance->ttsnoopWin_mainwin, "white"),
                NULL);
    }
    if (instance->ttsnoopWin_form == NULL)
        return -1;

    return 0;
}



