static int 
dtb_ttsnoop_ttsnoop_pane_create(
    DtbTtsnoopTtsnoopWinInfo instance,
    Widget parent
)
{
    Arg	args[53];	/* need 48 args (add 5 to be safe) */
    int	n = 0;
    static DtbObjectHelpDataRec	help_data = {
        "ttsnoop(1)\nDtTerm(3)\n",
        "",
        "",
    };
    
    if (instance->ttsnoopPane_scrolledwin == NULL) {
        n = 0;
        XtSetArg(args[n], XmNbottomOffset, 0);  ++n;
        XtSetArg(args[n], XmNbottomAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNrightOffset, 0);  ++n;
        XtSetArg(args[n], XmNrightAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNleftOffset, 0);  ++n;
        XtSetArg(args[n], XmNleftAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNtopOffset, 0);  ++n;
        XtSetArg(args[n], XmNtopAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNblinkRate, 0);  ++n;
        XtSetArg(args[n], XmNspacing, 0);  ++n;
        XtSetArg(args[n], XmNscrollBarDisplayPolicy, XmAUTOMATIC);  ++n;
        XtSetArg(args[n], XmNvisualPolicy, XmVARIABLE);  ++n;
        XtSetArg(args[n], XmNscrollingPolicy, XmAPPLICATION_DEFINED);  ++n;
        XtSetArg(args[n], XmNy, 0);  ++n;
        XtSetArg(args[n], XmNx, 0);  ++n;
        instance->ttsnoopPane_scrolledwin =
            XmCreateScrolledWindow(parent,
                "ttsnoopPane_scrolledwin", args, n);
        /*
         * Add help callback
         */
        XtAddCallback(instance->ttsnoopPane_scrolledwin,
            XmNhelpCallback, dtb_help_dispatch,
            (XtPointer)&help_data);
    }
    if (instance->ttsnoopPane_scrolledwin == NULL)
        return -1;

    if (instance->ttsnoopPane_vscrollbar == NULL) {
        instance->ttsnoopPane_vscrollbar =
            XtVaCreateWidget("ttsnoopPane_vscrollbar",
                xmScrollBarWidgetClass,
                instance->ttsnoopPane_scrolledwin,
                XmNorientation, XmVERTICAL,
                NULL);
    }
    if (instance->ttsnoopPane_vscrollbar == NULL)
        return -1;

    if (instance->ttsnoopPane == NULL) {
        instance->ttsnoopPane =
            XtVaCreateWidget("ttsnoopPane",
                dtTermWidgetClass,
                instance->ttsnoopPane_scrolledwin,
                XmNcolumns, 80,
                XmNrows, 24,
                NULL);
    }
    if (instance->ttsnoopPane == NULL)
        return -1;

    return 0;
}



static int 
dtb_ttsnoop_ttsnoop_win_label_create(
    DtbTtsnoopTtsnoopWinInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    
    label_xmstring = XmStringCreateLocalized("  ");
    if (instance->ttsnoopWin_label == NULL) {
        instance->ttsnoopWin_label =
            XtVaCreateWidget("ttsnoopWin_label",
                xmLabelWidgetClass,
                parent,
                XmNbottomAttachment, XmATTACH_NONE,
                XmNrightAttachment, XmATTACH_NONE,
                XmNleftOffset, 1,
                XmNleftAttachment, XmATTACH_FORM,
                XmNtopOffset, 1,
                XmNtopAttachment, XmATTACH_FORM,
                XmNrecomputeSize, True,
                XmNalignment, XmALIGNMENT_BEGINNING,
                XmNy, 1,
                XmNx, 1,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->ttsnoopWin_label == NULL)
        return -1;

    return 0;
}

